262	    /** Change a claim's status; a settle fixes the due as of a day when one is given (null: now). */
263	    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to, String reason,
264	            boolean judgeSettle, LocalDate on) {
265	        Claim claim = lock(sheetId, claimId);
266	        BigDecimal dueThen = on == null ? null : dueAsOf(sheetId, claim, on);
267	        refuseClosed(sheetId, claim.getDueBy());
268	        String voidReason = to == ClaimStatus.VOID ? voidReasons.required(sheetId, reason) : null;
269	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
270	            return voidSettled(sheetId, user, claim, voidReason);
271	        }
272	        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
273	            throw new ResponseStatusException(HttpStatus.CONFLICT,
274	                    "A " + claim.getStatus() + " claim cannot become " + to);
275	        }
276	        String action = switch (to) {
277	            case OPEN -> "open";
278	            case SETTLED -> "settle";
279	            default -> "void";
280	        };
281	        if (!roles.may(sheetId, user, action)) {
282	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
283	        }
284	        if (to == ClaimStatus.OPEN) {
285	            refuseFlagged(sheetId, user, claim);
286	            refuseUnnoted(sheetId, claim);
287	            refuseOverCap(sheetId, claim);
288	        }
289	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
290	            throw new ResponseStatusException(HttpStatus.CONFLICT,
291	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
292	        }
293	        if (to == ClaimStatus.SETTLED && judgeSettle) {
294	            refuseSameHands(user, claim);
295	            refuseUnproved(sheetId, claim);
296	        }
297	        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
298	                ? ClaimStatus.PENDING
299	                : to == ClaimStatus.OPEN && overReviewThreshold(sheetId, claim) ? ClaimStatus.REVIEW : to;
300	        return rollup.tracking(sheetId, user, () -> {
301	            Person person = person(sheetId, claim.getPersonId());
302	            if (becomes == ClaimStatus.SETTLED) {
303	                // Settling fixes the due at what it is now, while the claim is still open (the figure a
304	                // statement bound it to, if any, and its late charge); later changes to rates, the
305	                // late percent and the sheet's today do not alter it.
306	                claim.setSettledDue(dueThen != null ? dueThen : dues.figure(sheetId, person, claim));
307	            }
308	            // A void claim keeps the number it had (never reused).
309	            claim.setStatus(becomes);
310	            if (becomes == ClaimStatus.VOID) {
311	                claim.setVoidReason(voidReason);
312	            }
313	            if (becomes == ClaimStatus.OPEN) {
314	                claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
315	            }
316	            if (becomes == ClaimStatus.OPEN || becomes == ClaimStatus.REVIEW) {
317	                claim.setOpenedBy(user);
318	            }
319	            logStatus(sheetId, user, person, claim);
320	            Claim saved = claims.saveAndFlush(claim);
321	            String event = switch (becomes) {
322	                case OPEN -> "CLAIM_OPENED";
323	                case REVIEW -> "CLAIM_REVIEW";
324	                case PENDING -> "CLAIM_PENDING";
325	                case SETTLED -> "CLAIM_SETTLED";
326	                case VOID -> "CLAIM_VOIDED";
327	                case DRAFT, DELETED -> throw new IllegalStateException("a claim is deleted or restored apart");
328	            };
329	            String line = record(event, sheetId, user, person, saved);
330	            if (becomes == ClaimStatus.SETTLED) {
331	                line += " due=" + dueText(saved.getSettledDue());
332	                if (on != null) {
333	                    line += " on=" + on;
334	                }
335	            }
336	            line += reasonText(voidReason);
337	            audit.recordOnCommit(line);
338	            if (becomes == ClaimStatus.SETTLED) {
339	                watches.notifyWatchers(sheetId, user, person, saved.getNumber());
340	            }
341	            return saved;
342	        });
343	    }
