345	    /** A claim's due as it stood at the end of a day on or before the sheet's today, worked out as
346	     *  the sheet as of that day works it out. Refused (400) when the day is after the sheet's today,
347	     *  or when the claim or its person was not on the sheet yet then. */
348	    private BigDecimal dueAsOf(String sheetId, Claim claim, LocalDate on) {
349	        if (on.isAfter(sheets.today(sheetId))) {
350	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
351	                    "A claim cannot be settled as of a day after the sheet's today");
352	        }
353	        History.SheetAsOf then = history.asOf(sheetId, on);
354	        Claim claimThen = then.claims().stream().filter(c -> claim.getId().equals(c.getId())).findFirst()
355	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
356	                        "The claim was not on the sheet yet on that day"));
357	        Person personThen = then.person(claimThen.getPersonId())
358	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
359	                        "The claim's person was not on the sheet yet on that day"));
360	        return dues.figure(then.basis(), personThen, claimThen);
361	    }
