368	        Claim claim = lock(sheetId, claimId);
369	        refuseClosed(sheetId, claim.getDueBy());
370	        if (claim.getStatus() != ClaimStatus.REVIEW) {
371	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a claim in REVIEW can be reviewed");
372	        }
373	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
374	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can review a claim");
375	        }
376	        refuseOverCap(sheetId, claim);
377	        return rollup.tracking(sheetId, user, () -> {
378	            Person person = person(sheetId, claim.getPersonId());
379	            audit.recordOnCommit(record("CLAIM_REVIEWED", sheetId, user, person, claim));
380	            claim.setStatus(ClaimStatus.OPEN);
381	            claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
382	            logStatus(sheetId, user, person, claim);
383	            Claim saved = claims.saveAndFlush(claim);
384	            audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, saved));
385	            return saved;
386	        });
387	    }
