389	    /** Delete a draft claim: it counts nowhere, and cannot be edited, opened or voided. Refused when
390	     *  the claim is not a draft, or its period is closed. */
391	    @Transactional
392	    public Claim delete(String sheetId, String user, long claimId) {
393	        Claim claim = lock(sheetId, claimId);
394	        refuseClosed(sheetId, claim.getDueBy());
395	        if (!claim.getStatus().canBecome(ClaimStatus.DELETED) || claim.editLockedFor(user)) {
396	            throw new ResponseStatusException(HttpStatus.CONFLICT,
397	                    "A " + claim.getStatus() + " claim cannot be deleted, nor one another user is editing");
398	        }
399	        return rollup.tracking(sheetId, user, () -> {
400	            Person person = person(sheetId, claim.getPersonId());
401	            claim.setStatus(ClaimStatus.DELETED);
402	            claim.setEditLockedBy(null);
403	            logStatus(sheetId, user, person, claim);
404	            Claim saved = claims.saveAndFlush(claim);
405	            audit.recordOnCommit(record("CLAIM_DELETED", sheetId, user, person, saved));
406	            return saved;
