436	    /** Void a settled claim: only a steward may, within {@value #VOID_SETTLED_DAYS} days of its
437	     *  settlement (the first SETTLED line of its status log) by the sheet's today. It keeps its
438	     *  number and settled due, which leaves every total; the record ends with the figure reversed. */
439	    private Claim voidSettled(String sheetId, String user, Claim claim, String voidReason) {
440	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
441	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a settled claim");
442	        }
443	        LocalDate today = sheets.today(sheetId);
444	        LocalDate settled = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.SETTLED)
445	                .map(ClaimLog::getOn).findFirst().orElse(null);
446	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
447	            throw new ResponseStatusException(HttpStatus.CONFLICT,
448	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement");
449	        }
450	        return rollup.tracking(sheetId, user, () -> {
451	            Person person = person(sheetId, claim.getPersonId());
452	            BigDecimal reversed = dues.figure(sheetId, person, claim);
453	            claim.setStatus(ClaimStatus.VOID);
454	            claim.setVoidReason(voidReason);
455	            logStatus(sheetId, user, person, claim);
456	            Claim saved = claims.saveAndFlush(claim);
457	            audit.recordOnCommit(record("CLAIM_VOIDED", sheetId, user, person, saved) + " reversed=" + dueText(reversed)
458	                    + reasonText(voidReason));
459	            return saved;
460	        });
461	    }
