511	    /** Remind an open or pending claim: it is reminded on the sheet's today. Refused when the claim
512	     *  is in any other status, and when it was already reminded on the sheet's today. It changes no
513	     *  figure. A reminder at least the sheet's escalation gap after the claim's previous one escalates
514	     *  the claim, once ever. */
515	    @Transactional
516	    public Claim remind(String sheetId, String user, long claimId) {
517	        Claim claim = lock(sheetId, claimId);
518	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
519	            throw new ResponseStatusException(HttpStatus.CONFLICT,
520	                    "A " + claim.getStatus() + " claim cannot be reminded");
521	        }
522	        LocalDate today = sheets.today(sheetId);
523	        if (today.equals(claim.getRemindedOn())) {
524	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
525	                    "The claim was already reminded today");
526	        }
527	        Person person = person(sheetId, claim.getPersonId());
528	        LocalDate previous = claim.getRemindedOn();
529	        Integer gap = sheets.escalateAfter(sheetId);
530	        boolean escalate = gap != null && previous != null && !claim.isEscalated()
531	                && !previous.plusDays(gap).isAfter(today);
532	        claim.remindOn(today);
533	        if (escalate) {
534	            claim.escalate();
535	        }
536	        Claim saved = claims.saveAndFlush(claim);
537	        audit.recordOnCommit(record("REMIND", sheetId, user, person, saved));
538	        if (escalate) {
539	            audit.recordOnCommit(record("ESCALATE", sheetId, user, person, saved));
540	        }
541	        return saved;
542	    }
