612	    /** Re-settle a settled claim: its due is fixed again at the figure it would have today as an open
613	     *  claim bound by no statement (today's rates, grades, floor and late charge). Refused unless the
614	     *  claim is settled, the user is a steward, and the claim's period is open. */
615	    @Transactional
616	    public Claim resettle(String sheetId, String user, long claimId) {
617	        Claim claim = lock(sheetId, claimId);
618	        refuseClosed(sheetId, claim.getDueBy());
619	        if (claim.getStatus() != ClaimStatus.SETTLED) {
620	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled");
621	        }
622	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
623	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim");
624	        }
625	        return rollup.tracking(sheetId, user, () -> {
626	            Person person = person(sheetId, claim.getPersonId());
