667	    /** Move a claim as {@link #reassign(String, String, long, long)} does; a bulk move ({@code
668	     *  inBulk}) also takes a claim that is already the person's, listing it as their newest. */
669	    @Transactional
670	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId, boolean inBulk) {
671	        Claim claim = lock(sheetId, claimId);
672	        if (!roles.may(sheetId, user, "reassign")) {
673	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
674	        }
675	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
676	                || claim.getStatus() == ClaimStatus.DELETED) {
677	            throw new ResponseStatusException(HttpStatus.CONFLICT,
678	                    "A " + claim.getStatus() + " claim cannot be reassigned");
679	        }
680	        if (!inBulk && claim.getPersonId() == toPersonId) {
681	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's");
682	        }
683	        refuseClosed(sheetId, claim.getDueBy());
684	        Person from = person(sheetId, claim.getPersonId());
685	        Person to = person(sheetId, toPersonId);
686	        refuseRetired(to, claim.getDate());
687	        return rollup.tracking(sheetId, user, () -> {
688	            claim.moveTo(to.getId(), claims.nextListed());
689	            if (claim.getNumber() != null) {
690	                // a moved claim takes the next number; its old one is never used again
691	                claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
692	            }
693	            Claim saved = claims.saveAndFlush(claim);
694	            audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
695	                    + " from=" + from.getName() + " to=" + to.getName());
696	            return saved;
697	        });
698	    }
