775	    /** Split an amount (above 0.00 and below the claim's amount) off an open claim: it keeps the rest
776	     *  of its amount and loses any figure a statement bound it to, and a new open claim of the amount,
777	     *  the same date and note, the next number, opened by the user and due by the terms in force on
778	     *  the date, is listed as its person's newest claim. Refused when the claim is not open (or is
779	     *  deferred), its period is closed, the amount is out of range, or the permission matrix does not
780	     *  allow the user's role to open a claim. */
781	    @Transactional
782	    public Split split(String sheetId, String user, long claimId, BigDecimal part) {
783	        Claim claim = lock(sheetId, claimId);
784	        refuseClosed(sheetId, claim.getDueBy());
785	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
786	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an open claim that is not deferred can be split");
787	        }
788	        if (!roles.may(sheetId, user, "open")) {
789	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
790	        }
791	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
792	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
793	                    "The amount split off must be above 0.00 and below the claim's amount");
794	        }
795	        return rollup.tracking(sheetId, user, () -> {
796	            Person person = person(sheetId, claim.getPersonId());
797	            int terms = terms(sheetId, person, sheets.today(sheetId));
798	            LocalDate dueBy = holidays.businessDaysAfter(sheetId, claim.getDate(), terms);
799	            Claim draft = claim.splitOff(part, nextNumber(sheetId, dueBy), user, dueBy, terms);
800	            logStatus(sheetId, user, person, draft);
801	            Claim original = claims.saveAndFlush(claim);
802	            Claim split = claims.saveAndFlush(draft);
803	            audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original) + " into=" + split.getNumber());
804	            audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, split));
805	            return new Split(original, split);
806	        });
807	    }
