809	    /** Part-settle an open claim: split the amount off it as {@link #split} does, and settle the new
810	     *  claim at once as the settle button does (left PENDING when over the clerk limit). The four-eyes
811	     *  and proof rules are judged on the original claim, before the split; any refusal of the split or
812	     *  the settle refuses the whole and changes nothing. Returns the original and the new claim. */
813	    @Transactional
814	    public Split settlePart(String sheetId, String user, long claimId, BigDecimal part) {
815	        Claim claim = lock(sheetId, claimId);
816	        if (claim.getStatus() != ClaimStatus.OPEN) {
817	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an open claim can be part-settled");
818	        }
819	        if (!roles.may(sheetId, user, "settle")) {
820	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not settle a claim");
821	        }
822	        refuseSameHands(user, claim);
823	        refuseUnproved(sheetId, claim);
824	        Split split = split(sheetId, user, claimId, part);
825	        return new Split(split.original(),
826	                changeStatus(sheetId, user, split.split().getId(), ClaimStatus.SETTLED, null, false));
827	    }
