838	     *  it is not pending, the user is neither, or its period is closed. */
839	    private Claim lockPending(String sheetId, String user, long claimId) {
840	        Claim claim = lock(sheetId, claimId);
841	        refuseClosed(sheetId, claim.getDueBy());
842	        if (claim.getStatus() != ClaimStatus.PENDING) {
843	            throw new ResponseStatusException(HttpStatus.CONFLICT,
844	                    "Only a PENDING claim can be approved or rejected");
845	        }
846	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))
847	                && !person(sheetId, claim.getPersonId()).isApprover(user)) {
848	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
849	                    "Only a steward or the person's approver can approve or reject a claim");
850	        }
851	        return claim;
852	    }
