854	    /** Log the status the claim has now, changed by the user on the sheet's today, with its due as
855	     *  computed at this moment. */
856	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
857	        claim.logStatus(user, sheets.today(sheetId), dues.figure(sheetId, person, claim));
858	    }
859	
860	    private Claim lock(String sheetId, long claimId) {
861	        return claims.lockByIdAndSheetId(claimId, sheetId)
862	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
863	    }
864	
865	    private static String dueText(BigDecimal due) {
866	        return due == null ? "n/a" : due.setScale(2).toPlainString();
867	    }
868	
869	    /** The number for a claim due by the day opened now: under period numbering, the next in its period
870	     *  (<period name>-<n>), or for one in no period the next X-<n>; otherwise the next on the sheet
871	     *  within the fiscal year of its due-by day (<FY>-<n>). */
872	    public String nextNumber(String sheetId, LocalDate dueBy) {
873	        if (!sheets.periodNumbering(sheetId)) {
874	            return sheets.nextClaimNumber(sheetId, dueBy);
875	        }
876	        return periods.findOn(sheetId, dueBy)
877	                .map(p -> {
878	                    periods.advanceClaimNumber(p.getId());
879	                    return p.getName() + "-" + periods.lastClaimNumber(p.getId());
880	                })
881	                .orElseGet(() -> "X-" + sheets.nextUnperiodNumber(sheetId));
882	    }
883	
884	    /** The claim a claim of the amount corrects: none for an amount of 0.00 or more; for a correction
885	     *  (a negative amount), the one of the number given, which must be a settled claim of the person,
886	     *  or else it is refused; refused as well when it exceeds what remains of that claim: its amount
887	     *  less the corrections already made against it (VOID and DELETED ones, and the claim being
888	     *  edited, left out). */
889	    private Claim corrected(String sheetId, long personId, BigDecimal amount, String corrects, Long editing) {
890	        if (amount.signum() >= 0) {
891	            return null;
892	        }
893	        Claim corrected = (corrects == null ? Optional.<Claim>empty()
894	                : claims.findBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED))
895	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
896	                        "A negative amount must correct a settled claim of the same person"));
897	        BigDecimal remains = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId).stream()
898	                .filter(c -> corrected.getNumber().equals(c.getCorrects()) && !c.getId().equals(editing)
899	                        && c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
900	                .map(Claim::getAmount).reduce(corrected.getAmount(), BigDecimal::add);
901	        if (amount.negate().compareTo(remains) > 0) {
902	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
903	                    "A correction may not exceed the " + remains + " that remains of claim " + corrects);
904	        }
905	        return corrected;
906	    }
907	
908	    /** Refuse opening a claim of a person flagged on the sheet's today unless the user is a steward. */
909	    private void refuseFlagged(String sheetId, String user, Claim claim) {
910	        if (person(sheetId, claim.getPersonId()).isFlaggedOn(sheets.today(sheetId))
911	                && !SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
912	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
913	                    "Only a steward can open a claim of a flagged person");
914	        }
915	    }
916	
917	    /** Refuse a change to a claim due by the day when the day falls inside a closed period. */
918	    private void refuseClosed(String sheetId, LocalDate day) {
919	        if (periods.closedOn(sheetId, day)) {
920	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's period is closed");
921	        }
922	    }
923	
924	    /** Whether a clerk is settling a claim whose due is above the clerk limit in force on the sheet's today (its person's
925	     *  grade's when one is set, or else the sheet's); a claim with no due (n/a) is within any limit, and a steward settles
926	     *  anything. */
927	    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
928	        Person person = person(sheetId, claim.getPersonId());
929	        BigDecimal limit = sheets.clerkLimitFor(sheetId, person.gradeOn(sheets.today(sheetId)));
930	        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
931	            return false;
932	        }
933	        BigDecimal due = dues.figure(sheetId, person, claim);
934	        return due != null && due.compareTo(limit) > 0;
935	    }
936	
937	    /** Refuse settling or approving a claim whose due is above the proof threshold in force on the
938	     *  claim's date (its person's grade's on that date when one is set, or else the sheet's) when it
939	     *  has no proofs, or, while the sheet has proof kinds, no proof of one of them; a claim with no
940	     *  due (n/a) and a claim with no threshold need none. */
941	    private void refuseUnproved(String sheetId, Claim claim) {
942	        if (claim.getProofs() > 0
943	                && sheets.proofKinds(sheetId).stream().allMatch(k -> claim.getProofsOf(k) > 0)) {
944	            return;
945	        }
946	        Person person = person(sheetId, claim.getPersonId());
947	        BigDecimal threshold = sheets.proofThresholdFor(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
948	        if (threshold == null) {
949	            return;
950	        }
951	        BigDecimal due = dues.figure(sheetId, person, claim);
952	        if (due != null && due.compareTo(threshold) > 0) {
953	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
954	                    "A claim whose due is above the proof threshold needs a proof of each kind the sheet lists first");
955	        }
956	    }
957	
958	    /** Refuse opening a claim whose period caps its person's claims when the person already has
959	     *  that many open or pending claims due inside it; the period stays locked until the transaction
960	     *  ends, so two claims opened in it at once are counted one after the other. */
961	    private void refuseOverCap(String sheetId, Claim claim) {
962	        periods.findOn(sheetId, claim.getDueBy())
963	                .filter(p -> p.getClaimCap() != null)
964	                .flatMap(p -> periods.lockByIdAndSheetId(p.getId(), sheetId))
965	                .ifPresent(p -> {
966	                    if (claims.countOpenDueBetween(sheetId, claim.getPersonId(), p.getFromDate(), p.getToDate())
967	                            >= p.getClaimCap()) {
968	                        throw new ResponseStatusException(HttpStatus.CONFLICT,
969	                                "The person already has " + p.getClaimCap() + " open claims in period " + p.getName());
970	                    }
971	                });
972	    }
973	
974	    /** Refuse opening a claim with an empty note whose due is above the sheet's note threshold in
975	     *  force on the claim's date; a claim with no due (n/a) and a sheet with no threshold need none. */
976	    private void refuseUnnoted(String sheetId, Claim claim) {
977	        BigDecimal threshold = sheets.noteThreshold(sheetId, claim.getDate());
978	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
979	            return;
980	        }
981	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
982	        if (due != null && due.compareTo(threshold) > 0) {
983	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
984	                    "A claim whose due is above the note threshold needs a note before it is opened");
985	        }
986	    }
987	
988	    /** Whether a claim opened now goes to review: its due is above the sheet's review threshold in
989	     *  force on the claim's date; a claim with no due (n/a) and a sheet with no threshold do not. */
990	    private boolean overReviewThreshold(String sheetId, Claim claim) {
991	        BigDecimal threshold = sheets.reviewThreshold(sheetId, claim.getDate());
992	        if (threshold == null) {
993	            return false;
994	        }
995	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
996	        return due != null && due.compareTo(threshold) > 0;
997	    }
998	
999	    /** Refuse a claim of the person dated after the day they are retired from, or after the from-date
1000	     *  and before the to-date of one of their past retirements. */
1001	    private static void refuseRetired(Person person, LocalDate day) {
1002	        if ((person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom()))
1003	                || person.isWithinPastRetirement(day)) {
1004	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
1005	                    "A claim cannot be dated after the person's retirement");
1006	        }
1007	    }
1008	
1009	    /** The terms a claim of the person made on the day (the sheet's today then) has its due-by fixed
1010	     *  with (the terms-th business day after its date, skipping every Saturday, Sunday and holiday of
1011	     *  the sheet): the first of the person's own terms, those of the grade they had on the day and the
1012	     *  sheet's, each as in force on the day. */
1013	    private int terms(String sheetId, Person person, LocalDate on) {
1014	        Integer own = person.termsOn(on);
1015	        return own != null ? own : sheets.termsFor(sheetId, person.gradeOn(on), on);
1016	    }
1017	
1018	    /** Refuse a reference (null: none) another claim of the sheet than the one given (null: any) has,
1019	     *  comparing without regard to case. */
1020	    /** The tags ever used on the sheet, in order. */
1021	    @Transactional(readOnly = true)
1022	    public List<String> tags(String sheetId) {
1023	        return sheetTags.findBySheetIdOrderByTagAsc(sheetId).stream().map(SheetTag::getTag).toList();
1024	    }
1025	
1026	    /** Keep each of the tags (as {@link Tags} stores them) as used on the sheet. */
1027	    public void keepTags(String sheetId, String tags) {
1028	        for (String tag : Tags.of(tags)) {
1029	            if (!sheetTags.existsBySheetIdAndTag(sheetId, tag)) {
1030	                sheetTags.save(new SheetTag(sheetId, tag));
1031	            }
1032	        }
1033	    }
1034	
1035	    public void refuseRefUsed(String sheetId, String ref, Long exceptId) {
1036	        if (ref != null && claims.refUsed(sheetId, ref, exceptId)) {
1037	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1038	                    "The reference \"" + ref + "\" is already used on this sheet");
1039	        }
1040	    }
1041	
1042	    private Person person(String sheetId, long personId) {
1043	        return people.findByIdAndSheetId(personId, sheetId)
1044	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
1045	    }
1046	
1047	    /** An audit record about a claim; one that has a number carries it at the end. */
1048	    /** The end of a void's record: its reason, when one was given. */
1049	    private static String reasonText(String voidReason) {
1050	        return voidReason == null ? "" : " reason=" + voidReason;
1051	    }
1052	
1053	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
1054	        String number = claim.getNumber();
1055	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
1056	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
1057	                + (number != null ? " number=" + number : "");
1058	    }
1059	}
