284	    public List<Person> retire(String sheetId, String user, Set<Long> personIds, LocalDate from) {
285	        if (SheetRole.VIEWER.equals(roles.roleOf(sheetId, user))) {
286	            return List.of();
287	        }
288	        List<Person> chosen = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
289	                .filter(p -> personIds.contains(p.getId())).toList();
290	        if (chosen.size() != personIds.size()) {
291	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet");
292	        }
293	        return chosen.stream().map(p -> retire(sheetId, user, p, from)).toList();
294	    }
