298	    public Person retire(String sheetId, String user, long personId, LocalDate from) {
299	        Person person = people.findByIdAndSheetId(personId, sheetId)
300	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
301	        return retire(sheetId, user, person, from);
