304	    /** Retire the person from a day (null: the sheet's today), recording it. */
305	    private Person retire(String sheetId, String user, Person person, LocalDate from) {
306	        LocalDate on = from != null ? from : sheets.today(sheetId);
307	        return rollup.tracking(sheetId, user, () -> {
308	            person.setRetiredFrom(on);
309	            Person saved = saveUnique(person);
310	            audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
311	                    + " from=" + on);
312	            return saved;
313	        });
314	    }
