316	    /** Unretire a person on the sheet's today: their retirement is kept as a past one, to that day.
317	     *  Refused when they are not retired. */
318	    @Transactional
319	    public Person unretire(String sheetId, String user, long personId) {
320	        Person person = people.findByIdAndSheetId(personId, sheetId)
321	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
322	        if (!person.isRetired()) {
323	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a retired person can be unretired");
324	        }
325	        LocalDate on = sheets.today(sheetId);
326	        return rollup.tracking(sheetId, user, () -> {
327	            person.unretire(on);
328	            Person saved = saveUnique(person);
329	            audit.recordOnCommit("PERSON_UNRETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
330	                    + " on=" + on);
331	            return saved;
332	        });
333	    }
