335	    /** Put a person on hold from a day (null: the sheet's today) to a day (null: open-ended),
336	     *  keeping their other holds; refused when the to-date is before the from-date. */
337	    @Transactional
338	    public Person hold(String sheetId, String user, long personId, LocalDate from, LocalDate to) {
339	        Person person = people.findByIdAndSheetId(personId, sheetId)
340	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
341	        LocalDate on = from != null ? from : sheets.today(sheetId);
342	        if (to != null && to.isBefore(on)) {
343	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts");
344	        }
345	        return rollup.tracking(sheetId, user, () -> {
346	            person.addHold(on, to);
347	            Person saved = saveUnique(person);
348	            audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
349	                    + " from=" + on);
350	            return saved;
351	        });
352	    }
