354	    /** Flag a person with a reason (kept trimmed) until a day (included; null: the sheet's
355	     *  today), replacing any flag they had. Refused unless the user is a steward (403) and the reason is not blank (400). */
356	    @Transactional
357	    public Person flag(String sheetId, String user, long personId, String reason, LocalDate until) {
358	        Person person = people.findByIdAndSheetId(personId, sheetId)
359	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
360	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
361	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can flag a person");
362	        }
363	        if (reason == null || reason.isBlank()) {
364	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Give a reason for the flag");
365	        }
366	        String why = reason.trim();
367	        LocalDate last = until != null ? until : sheets.today(sheetId);
368	        person.flag(why, last);
369	        Person saved = saveUnique(person);
370	        audit.recordOnCommit("PERSON_FLAGGED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
371	                + " reason=" + why + " until=" + last);
372	        return saved;
373	    }
