375	    /** Set the person's approver: the user (kept trimmed; blank: none) who may approve or reject
376	     *  their pending claims as a steward may. */
377	    @Transactional
378	    public Person setApprover(String sheetId, String user, long personId, String approver) {
379	        Person person = people.findByIdAndSheetId(personId, sheetId)
380	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
381	        String who = approver == null || approver.isBlank() ? null : approver.trim();
382	        person.setApprover(who);
383	        Person saved = saveUnique(person);
384	        audit.recordOnCommit("APPROVER_SET sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
385	                + " user=" + (who == null ? "" : who));
386	        return saved;
387	    }
