389	    /** A record of the person with the grade in force on the sheet's today. */
390	    private static String record(String event, String sheetId, String user, Person person, LocalDate today) {
391	        return event + " sheet=" + sheetId + " by=" + user + " name=" + person.getName() + " grade="
392	                + person.gradeOn(today);
393	    }
