395	    /** Save, refusing a name or contact another user took on the sheet in the meantime, or a person
396	     *  another user saved in the meantime. */
397	    private Person saveUnique(Person person) {
398	        try {
399	            return people.saveAndFlush(person);
400	        } catch (DataIntegrityViolationException e) {
401	            String constraint = String.valueOf(e.getMostSpecificCause().getMessage()).toUpperCase(Locale.ROOT);
402	            throw constraint.contains("PERSON_SHEET_CONTACT_UNIQUE") ? contactInUse() : nameInUse();
403	        } catch (OptimisticLockingFailureException e) {
404	            throw changedMeanwhile();
405	        }
406	    }
407	
408	    private static ResponseStatusException changedMeanwhile() {
409	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
410	                "Someone else saved this person in the meantime");
411	    }
412	
413	    private static ResponseStatusException contactInUse() {
414	        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already held on this sheet");
415	    }
416	
417	    private static ResponseStatusException nameInUse() {
418	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet");
419	    }
