183	    /** The people on the sheet; as of a day when one is given, as they stood at the end of it (see
184	     *  {@link History}), that day standing in for the sheet's today. */
185	    @GetMapping
186	    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
187	            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
188	            LocalDate asOf) {
189	        String sheet = sheetId.trim();
190	        if (asOf != null) {
191	            Map<Long, StatementSummary> then = statements.summaries(sheet, asOf);
192	            Predicate<Person> clashingThen = service.clashing(sheet);
193	            Map<Long, Integer> place = new HashMap<>();
194	            List<Person> listed = service.list(sheet);
195	            for (int i = 0; i < listed.size(); i++) {
196	                place.put(listed.get(i).getId(), i);
197	            }
198	            return history.asOf(sheet, asOf).people().values().stream()
199	                    .sorted(Comparator.comparing((Person p) -> place.getOrDefault(p.getId(), Integer.MAX_VALUE))
200	                            .thenComparing(Person::getId))
201	                    .map(p -> PersonView.of(p, then.getOrDefault(p.getId(), StatementSummary.NONE), asOf,
202	                            clashingThen.test(p)))
203	                    .toList();
204	        }
205	        Map<Long, StatementSummary> summaries = statements.summaries(sheet);
206	        LocalDate today = sheets.today(sheet);
207	        Predicate<Person> clashing = service.clashing(sheet);
208	        return service.list(sheet).stream()
209	                .map(p -> PersonView.of(p, summaries.getOrDefault(p.getId(), StatementSummary.NONE), today,
210	                        clashing.test(p)))
211	                .toList();
212	    }
