91	    70	        for (Line line : lines) {
92	    71	            Period period = changed.computeIfAbsent(line.period().getId(), id -> periods.lockByIdAndSheetId(id, sheetId)
93	    72	                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet")));
94	    73	            period.addOpening(line.person().getId(), line.amount());
95	    74	            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + line.person().getName()
96	    75	                    + " period=" + period.getName() + " amount=" + line.amount().toPlainString());
97	    76	        }
98	    77	        List<Period> saved = periods.saveAllAndFlush(changed.values());
99	    78	        history.record(sheetId);
