108	    87	        }
109	    88	        String name = fields[0].trim();
110	    89	        Person person = name.isEmpty() ? null : people.findByNameOrAlias(sheetId, name).orElse(null);
111	    90	        if (person == null) {
112	    91	            throw refused(n, "no one named \"" + name + "\" on this sheet");
113	    92	        }
114	    93	        String periodName = fields[1].trim();
115	    94	        Period period = onSheet.stream().filter(p -> p.getName().equalsIgnoreCase(periodName)).findFirst()
