    53	            return SheetRole.STEWARD;
    54	        }
    55	        return revisions
    56	                .findFirstBySheetIdAndUserNameAndRecordedOnLessThanEqualOrderByRecordedOnDescIdDesc(sheetId, userName, day)
    57	                .map(RoleRevision::getRole)
