    70	    public Optional<String> delegatorOf(String sheetId, String userName) {
    71	        LocalDate today = sheets.today(sheetId);
    72	        return delegations
    73	                .findFirstBySheetIdAndUserNameAndFromDateLessThanEqualAndToDateGreaterThanEqualOrderByIdDesc(
    74	                        sheetId, userName, today, today)
