    84	    /** Delegate the steward role to a user name from a day (the sheet's today when none) to a day (the
    85	     *  from-day when none), inclusive. Refused unless the user was given the steward role, or when the
    86	     *  range ends before it starts. */
    87	    @Transactional
    88	    public synchronized Delegation delegate(String sheetId, String user, String userName, LocalDate from, LocalDate to) {
    89	        sheets.load(sheetId, user);
    90	        if (!SheetRole.STEWARD.equals(givenRoleOf(sheetId, user))) {
    91	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may delegate the steward role");
    92	        }
    93	        LocalDate start = from == null ? sheets.today(sheetId) : from;
    94	        LocalDate end = to == null ? start : to;
    95	        if (end.isBefore(start)) {
    96	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A delegation cannot end before it starts");
    97	        }
    98	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, userName, user, start, end));
