   104	    /** Whether a user name's role on the sheet may take an action of the permission matrix (open,
   105	     *  settle, void, reassign, close, reopen). */
   106	    @Transactional(readOnly = true)
   107	    public boolean may(String sheetId, String userName, String action) {
   108	        return sheets.rolesAllowed(sheetId, action).contains(roleOf(sheetId, userName));
   109	    }
   110	
   111	    /** Give a user name a role on the sheet, replacing the one it had. */
   112	    @Transactional
   113	    public synchronized SheetRole set(String sheetId, String user, String userName, String role) {
   114	        sheets.load(sheetId, user);
   115	        SheetRole given = roles.findBySheetIdAndUserName(sheetId, userName)
   116	                .orElseGet(() -> new SheetRole(sheetId, userName, role));
   117	        given.setRole(role);
   118	        SheetRole saved = roles.saveAndFlush(given);
   119	        revisions.saveAndFlush(new RoleRevision(sheetId, userName, role, sheets.today(sheetId)));
   120	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + userName + " role=" + role);
   121	        return saved;
   122	    }
