101	   101	    /** The next claim number on the sheet for a claim due by the day: <FY>-<n>, counting from 1 within
102	   102	     *  the fiscal year (by the sheet's fiscal start month) the day falls in; the sheets of a tree share
103	   103	     *  one sequence per fiscal year, so it is the next after the last number given within that fiscal
104	   104	     *  year on any sheet of the sheet's tree. */
105	   105	    @Transactional
106	   106	    public String nextClaimNumber(String id, LocalDate dueBy) {
107	   107	        // the tree's root row is locked until the transaction ends, so two claims opened on its
108	   108	        // sheets at once get one number each
109	   109	        String root = sheets.root(id);
110	   110	        sheets.lockClaimNumber(root);
111	   111	        if (sheets.lockClaimNumber(id) != 1) {
112	   112	            throw new IllegalStateException("No sheet " + id);
113	   113	        }
114	   114	        String fiscalYear = PeriodService.fiscalYear(dueBy, fiscalStartMonth(id));
115	   115	        List<String> tree = new ArrayList<>(sheets.descendants(root));
116	   116	        tree.add(root);
117	   117	        int next = fiscalNumbers.lastNumber(tree, fiscalYear) + 1;
118	   118	        FiscalClaimNumber last = fiscalNumbers.findById(new FiscalClaimNumber.Key(id, fiscalYear))
119	   119	                .orElseGet(() -> new FiscalClaimNumber(id, fiscalYear, 0));
120	   120	        last.setLastNumber(next);
121	   121	        fiscalNumbers.saveAndFlush(last);
122	   122	        return fiscalYear + "-" + next;
123	   123	    }
