632	   632	        String at = sheets.findById(id).map(Sheet::getParentId).orElse(null);
633	   633	        while (at != null && !at.equals(id) && tree.add(at)) {
634	   634	            at = sheets.findById(at).map(Sheet::getParentId).orElse(null);
635	   635	        }
636	   636	        Set<String> below = new HashSet<>();
637	   637	        Deque<String> next = new ArrayDeque<>(List.of(id));
638	   638	        while (!next.isEmpty()) {
639	   639	            for (Sheet child : sheets.findByParentId(next.pop())) {
640	   640	                if (!child.getId().equals(id) && below.add(child.getId())) {
641	   641	                    next.add(child.getId());
642	   642	                }
643	   643	            }
644	   644	        }
645	   645	        tree.addAll(below);
646	   646	        tree.retainAll(sheets.findAllById(tree).stream().map(Sheet::getId).toList());
647	   647	        return tree;
648	   648	    }
