262	   262	/** The sum of amounts (two-decimal text), added in cents so no rounding creeps in. */
263	   263	export function sumAmounts(amounts: string[]): string {
264	   264	  const cents = amounts.reduce((sum, a) => sum + Math.round(Number(a) * 100), 0);
265	   265	  return (cents / 100).toFixed(2);
