268	   268	/** Amounts added up, leaving out the single highest and the single lowest when there are three or
269	   269	 *  more. */
270	   270	export function trimmedSum(amounts: string[]): string {
271	   271	  if (amounts.length < 3) return sumAmounts(amounts);
272	   272	  const sorted = [...amounts].sort((a, b) => Number(a) - Number(b));
273	   273	  return sumAmounts(sorted.slice(1, -1));
274	   274	}
