288	   288	/** What a claim's late charge follows: the sheet's today and its late percents (each 30-day boundary
289	   289	 *  takes the one in force on it), and the grace days of each grade; and the sheet's rounding modes and
290	   290	 *  policy date, which decide how its live figures round. */
291	   291	export interface Lateness {
292	   292	  today: string | null;
293	   293	  /** The late percents recorded, each from its from-date, earliest first. */
294	   294	  pcts: DatedValue[];
295	   295	  /** The grace days recorded for each grade. */
296	   296	  graces: Graces;
297	   297	  /** The policy date set (yyyy-mm-dd); null when blank, the sheet's today then stands in. */
298	   298	  policyDate: string | null;
299	   299	  /** The rounding modes recorded (null: blank, none), each from its from-date, earliest first. */
300	   300	  roundings: DatedValue<RoundingMode | null>[];
301	   301	}
302	   302	
303	   303	/** Whether a claim's live figures round half up: by the rounding mode in force on its date, or,
304	   304	 *  when none is, when the date it rounds by is before the policy date in force (the one set, or
305	   305	 *  else the sheet's today); otherwise they round half to even. */
306	   306	export function roundsHalfUp(c: Claim, late: Lateness): boolean {
307	   307	  const mode = valueOn<RoundingMode | null>(late.roundings, c.date, null);
308	   308	  if (mode !== null) return mode === 'half-up';
309	   309	  const policy = late.policyDate ?? late.today;
310	   310	  return policy !== null && c.roundsBy < policy;
311	   311	}
312	   312	
313	   313	/** A claim's due figure: the one fixed when it was settled, or else the one its person's last statement bound it to
314	   314	 *  as it showed then, late charge included (n/a when it bound it to n/a), or else the greater of the sheet's floor in
315	   315	 *  force on the claim's date and its rate figure, with the late charge on that floored figure on top while overdue. The
316	   316	 *  rate figure is its live due at the rate in
317	   317	 *  force on the claim's date that applies to it (see {@link pctFor}) for the grade (the person's grade in force on that date), rounded by the rounding mode or policy date (a
318	   318	 *  settled claim's figure already holds the charge and the floor). A correction has no floor and no late charge. Null
319	   319	 *  when there is none. */
320	   320	export function claimDue(c: Claim, rates: Rate[], grade: Grade | undefined, floors: DatedValue[], late: Lateness): string | null {
321	   321	  if (c.settledDue !== null) return c.settledDue;
322	   322	  if (bound(c) && c.statedNa) return null;
323	   323	  if (bound(c) && c.statedDue !== null) return c.statedDue;
324	   324	  const figure = due(c.amount, grade === undefined ? undefined : pctFor(rates, grade, c), roundsHalfUp(c, late));
325	   325	  if (figure === null) return null;
326	   326	  const floored = correction(c) ? figure : atLeast(figure, valueOn(floors, c.date, STARTING_FLOOR));
327	   327	  return sumAmounts([floored, lateCharge(c, floored, late, grade)]);
328	   328	}
329	   329	
330	   330	/** The late charge on an overdue claim (its grade being its person's grade in force on its date): for each full
331	   331	 *  30 days it is overdue, the late percent in force on that boundary (its late-from plus 30, 60, 90 ... days) of its
332	   332	 *  figure plus the charges of the boundaries before it (the charge compounds), rounded like a due, the charges added
333	   333	 *  up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not overdue, on a correction, and when its
334	   334	 *  late charge is waived. */
335	   335	export function lateCharge(c: Claim, figure: string, late: Lateness, grade: Grade | undefined): string {
336	   336	  if (correction(c) || c.waived) return '0.00';
337	   337	  const grace = graceOn(late.graces, grade, c.date);
338	   338	  if (!overdue(c, late.today, grace) || late.today === null) return '0.00';
339	   339	  const from = Date.parse(lateFrom(c, grace));
340	   340	  const days = (Date.parse(late.today) - from) / 86_400_000;
341	   341	  const periods = Math.floor(days / 30);
342	   342	  if (periods <= 0) return '0.00';
343	   343	  const charges: string[] = [];
344	   344	  for (let n = 1; n <= periods; n++) {
345	   345	    const boundary = new Date(from + n * 30 * 86_400_000).toISOString().slice(0, 10);
346	   346	    const pct = valueOn(late.pcts, boundary, STARTING_LATE_PCT);
347	   347	    if (Number(pct) !== 0) charges.push(due(sumAmounts([figure, ...charges]), pct, roundsHalfUp(c, late)) ?? '0.00');
348	   348	  }
349	   349	  return sumAmounts(charges);
350	   350	}
