352	   352	/** The day a claim's lateness counts from: its due-by plus its grace days (those in force on its date
353	   353	 *  for its person's grade in force on that date). The due-by it shows is unchanged. */
354	   354	export function lateFrom(c: Claim, grace: number): string {
355	   355	  return grace === 0 ? c.dueBy : addDays(c.dueBy, grace);
356	   356	}
357	   357	
358	   358	/** Whether a claim in review is late: its review day (the sheet's today when it last went to review)
359	   359	 *  plus the sheet's review SLA days is before the sheet's today; never while there is no SLA. */
360	   360	export function reviewLate(c: Claim, today: string | null, sla: number | null): boolean {
361	   361	  if (c.status !== 'REVIEW' || today === null || sla === null) return false;
362	   362	  const day = c.log.filter((l) => l.status === 'REVIEW').at(-1)?.on;
363	   363	  return day !== undefined && addDays(day, sla) < today;
364	   364	}
365	   365	
366	   366	/** Whether a claim is overdue: it is open (or pending), not deferred, and its due-by plus its grace
367	   367	 *  days is before the sheet's today. */
368	   368	export function overdue(c: Claim, today: string | null, grace = 0): boolean {
369	   369	  return isOpen(c) && !deferred(c, today) && today !== null && lateFrom(c, grace) < today;
370	   370	}
