375	   375	    /** The settings view of a sheet as it stood at the end of a day. */
376	   376	    private SettingsView view(String id, History.SheetAsOf then) {
377	   377	        LocalDate day = then.day();
378	   378	        Function<String, BigDecimal> value = key -> then.setting(key, day).map(SettingValue::getValue).orElse(null);
379	   379	        Map<String, Integer> gradeTerms = new TreeMap<>();
380	   380	        for (String grade : List.of("A", "B", "C")) {
381	   381	            then.setting("terms-" + grade, day).ifPresent(v -> gradeTerms.put(grade, v.getValue().intValue()));
382	   382	        }
383	   383	        int terms = then.setting("terms", day).map(v -> v.getValue().intValue()).orElse(SheetService.STARTING_TERMS);
384	   384	        Map<String, Integer> gradeGraces = new TreeMap<>();
385	   385	        Map<String, List<SettingValue>> graces = new TreeMap<>();
386	   386	        for (String grade : List.of("A", "B", "C")) {
387	   387	            then.setting("grace-" + grade, day).map(SettingValue::getValue)
388	   388	                    .ifPresent(v -> gradeGraces.put(grade, v.intValue()));
389	   389	            graces.put(grade, then.recorded("grace-" + grade));
390	   390	        }
391	   391	        Map<String, BigDecimal> gradeProofThresholds = new TreeMap<>();
392	   392	        for (String grade : List.of("A", "B", "C")) {
393	   393	            then.setting("proof-threshold-" + grade, day).map(SettingValue::getValue)
394	   394	                    .ifPresent(v -> gradeProofThresholds.put(grade, v));
395	   395	        }
396	   396	        Map<String, BigDecimal> gradeClerkLimits = new TreeMap<>();
397	   397	        for (String grade : List.of("A", "B", "C")) {
398	   398	            then.setting("clerk-limit-" + grade, day).map(SettingValue::getValue)
399	   399	                    .ifPresent(v -> gradeClerkLimits.put(grade, v));
400	   400	        }
401	   401	        return SettingsView.of(value.apply("clerk-limit"), then.basis().floor(day), terms, then.basis().latePct(day),
402	   402	                then.policyDate(), service.periodNumberingFrom(id), gradeTerms, then.basis().cap(),
403	   403	                then.recorded("floor"), then.recorded("late-pct"), then.recorded("cap"),
404	   404	                value.apply("proof-threshold"), service.permissions(id), service.graceDays(id),
405	   405	                value.apply("note-threshold"), service.entryDate(id), gradeGraces, graces,
406	   406	                gradeProofThresholds, service.pot(id), service.parent(id), service.fiscalStartMonth(id),
407	   407	                service.alertThreshold(id),
408	   408	                then.setting(Rounding.KEY, day).map(SettingValue::getValue).flatMap(Rounding::ofCode),
409	   409	                then.recorded(Rounding.KEY), value.apply("review-threshold"), service.escalateAfter(id),
410	   410	                service.reviewSla(id), service.proofKinds(id), service.defaultGradeSet(id), gradeClerkLimits);
411	   411	    }
