7	     7	// The dated settings (the clerk limit, the cap, the floor, the terms and the late percent) as in force
8	     8	// on the sheet's today.
9	     9	export interface Settings {
10	    10	  /** The most due a clerk may settle, as text with two decimals; null when there is no limit. */
11	    11	  clerkLimit: string | null;
12	    12	  /** The least live due a claim has, as text with two decimals. */
13	    13	  floor: string;
14	    14	  /** The days after its date a claim is due by. */
15	    15	  terms: number;
16	    16	  /** The percent of its figure an overdue claim gains for every full 30 days, as text with two decimals. */
17	    17	  latePct: string;
18	    18	  /** The policy date (yyyy-mm-dd); null when blank, the sheet's today then stands in. */
19	    19	  policyDate: string | null;
20	    20	  /** The period numbering from date (yyyy-mm-dd); null when blank (off). */
21	    21	  periodNumberingFrom: string | null;
22	    22	  /** The terms each grade has of its own, by grade; a grade not in it takes the sheet's terms. */
23	    23	  gradeTerms: Partial<Record<Grade, number>>;
24	    24	  /** The most a person's due-total comes to, as text with two decimals; null when there is no cap. */
25	    25	  cap: string | null;
26	    26	  /** The floors recorded, each from its from-date, earliest first. */
27	    27	  floors: DatedValue[];
28	    28	  /** The late percents recorded, each from its from-date, earliest first. */
29	    29	  latePcts: DatedValue[];
30	    30	  /** The caps recorded (null: no cap), each from its from-date, earliest first. */
31	    31	  caps: DatedValue<string | null>[];
32	    32	  /** The due above which a claim needs a proof before it is settled or approved, as text with two
33	    33	   *  decimals; null when there is none. */
34	    34	  proofThreshold: string | null;
35	    35	  /** The due above which a claim cannot be opened with an empty note, as text with two decimals;
36	    36	   *  null when there is none. */
37	    37	  noteThreshold: string | null;
38	    38	  /** The due above which a claim goes to review when it is opened, as text with two decimals; null
39	    39	   *  when there is none. */
40	    40	  reviewThreshold: string | null;
41	    41	  /** The permission matrix: for each action, the comma separated roles that may take it; blank when
42	    42	   *  it keeps the standing rule. */
43	    43	  permissions: Record<PermAction, string>;
44	    44	  /** The grace days: when the sheet's today is changed, an open period whose to-date plus them is
45	    45	   *  before it is closed; null when blank (off). */
46	    46	  graceDays: number | null;
47	    47	  /** The escalation gap: reminding a claim this many days or more after its previous reminder
