    49	        List<Crew> all = crews.findBySheetIdOrderByIdAsc(sheetId);
    50	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
    51	                .collect(Collectors.toMap(Person::getId, Function.identity()));
    52	        Map<Long, List<CrewMember>> byCrew = members
    53	                .findByCrewIdInOrderByIdAsc(all.stream().map(Crew::getId).toList()).stream()
    54	                .collect(Collectors.groupingBy(CrewMember::getCrewId));
    55	        return all.stream().map(c -> new Listed(c, byId.get(c.getLeadPersonId()),
    56	                byCrew.getOrDefault(c.getId(), List.of()).stream()
    57	                        .map(m -> byId.get(m.getPersonId()))
    58	                        .filter(p -> p != null)
    59	                        .toList()))
    60	                .toList();
    61	    }
    62	
    63	    /** Add a crew with a (trimmed) name and a lead; refused when the name is blank or already a crew
    64	     *  or a pool of the sheet, or the lead is not a person of it. Its pool is added with it. */
    65	    @Transactional
    66	    public synchronized Listed add(String sheetId, String user, String name, long leadId) {
    67	        String text = name == null ? "" : name.trim();
    68	        if (text.isEmpty()) {
    69	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Enter a crew name");
    70	        }
    71	        sheets.load(sheetId, user);
    72	        Person lead = people.findByIdAndSheetId(leadId, sheetId)
    73	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
    74	        if (crews.existsBySheetIdAndName(sheetId, text) || pools.existsBySheetIdAndName(sheetId, text)) {
    75	            throw alreadyACrew();
    76	        }
    77	        Crew saved;
    78	        try {
    79	            saved = crews.saveAndFlush(new Crew(sheetId, text, lead.getId()));
    80	            Pool pool = Pool.ofCrew(sheetId, text, saved.getId());
    81	            pool.setAddedOn(sheets.today(sheetId));
    82	            pools.saveAndFlush(pool);
    83	        } catch (DataIntegrityViolationException e) {
    84	            throw alreadyACrew();
    85	        }
    86	        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + user + " name=" + text
    87	                + " lead=" + lead.getName());
    88	        return new Listed(saved, lead, List.of());
    89	    }
    90	
    91	    /** Add a person of the sheet to a crew; refused when they are its lead or already in it. */
    92	    @Transactional
    93	    public synchronized Listed addMember(String sheetId, String user, long crewId, long personId) {
    94	        Crew crew = crews.findByIdAndSheetId(crewId, sheetId)
    95	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such crew"));
    96	        Person person = people.findByIdAndSheetId(personId, sheetId)
    97	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
    98	        if (crew.getLeadPersonId().equals(personId)) {
    99	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person leads the crew");
   100	        }
   101	        if (members.existsByCrewIdAndPersonId(crewId, personId)) {
   102	            throw alreadyAMember();
   103	        }
   104	        try {
   105	            CrewMember m = new CrewMember(crewId, personId);
   106	            m.setAddedOn(sheets.today(sheetId));
   107	            members.saveAndFlush(m);
   108	        } catch (DataIntegrityViolationException e) {
   109	            throw alreadyAMember();
   110	        }
   111	        audit.recordOnCommit("CREW_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " crew=" + crew.getName()
   112	                + " name=" + person.getName());
   113	        return list(sheetId).stream().filter(l -> l.crew().getId().equals(crewId)).findFirst().orElseThrow();
   114	    }
