    21	    private final SheetService sheets;
    22	    private final Audit audit;
    23	
    24	    public WatchService(WatchRepository watches, PersonRepository people, SheetService sheets, Audit audit) {
    25	        this.watches = watches;
    26	        this.people = people;
    27	        this.sheets = sheets;
    28	        this.audit = audit;
    29	    }
    30	
    31	    /** The people the user watches on the sheet, in the order they started watching. */
    32	    @Transactional(readOnly = true)
    33	    public List<Watch> list(String sheetId, String user) {
    34	        return watches.findBySheetIdAndUserOrderByIdAsc(sheetId, user);
    35	    }
    36	
    37	    /** Start watching a person; refused when the user already watches them. */
    38	    @Transactional
    39	    public Watch watch(String sheetId, String user, long personId) {
    40	        Person person = person(sheetId, personId);
    41	        if (watches.findByPersonIdAndUser(person.getId(), user).isPresent()) {
    42	            throw alreadyWatching();
    43	        }
    44	        Watch saved;
    45	        try {
    46	            saved = watches.saveAndFlush(new Watch(sheetId, person.getId(), user, sheets.today(sheetId)));
    47	        } catch (DataIntegrityViolationException e) {
    48	            throw alreadyWatching();
    49	        }
    50	        audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
    51	        return saved;
    52	    }
    53	
    54	    /** Stop watching a person; refused when the user does not watch them. */
    55	    @Transactional
    56	    public void unwatch(String sheetId, String user, long personId) {
    57	        Person person = person(sheetId, personId);
    58	        Watch watch = watches.findByPersonIdAndUser(person.getId(), user)
    59	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "You do not watch this person"));
    60	        watches.delete(watch);
    61	        watches.flush();
    62	        audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
    63	    }
    64	
    65	    /** Tell each user watching the person, in the order they started watching, that a claim of
    66	     *  theirs was settled. Recorded once the change commits, after the records made before it. */
    67	    @Transactional(propagation = Propagation.MANDATORY)
    68	    public void notifyWatchers(String sheetId, String user, Person person, String number) {
    69	        for (Watch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
    70	            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUser()
    71	                    + " person=" + person.getName() + " number=" + number);
    72	        }
    73	    }
