873	  /** Whether a conflict on saving the form (an add when `id` is null) can only be its reference
874	   *  being in use: an add, or an edit of a draft no other user is editing. */
875	  private refClash(id: number | null): boolean {
876	    if (id === null) return true;
877	    const c = this.claims().find((x) => x.id === id);
878	    return c !== undefined && c.status === 'DRAFT'
879	      && (c.editLockedBy === null || c.editLockedBy === this.session.user());
