package net.officefloor.hq.app.role;


/** Refuses every change a viewer asks of a sheet (403), before it writes anything; only the
 *  requests marked {@link ViewerAllowed} go through. */
@Configuration
public class ViewerGuard implements HandlerInterceptor, WebMvcConfigurer {

    private final RoleService roles;

    public ViewerGuard(RoleService roles) {
        this.roles = roles;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this).addPathPatterns("/api/sheets/**");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || !(handler instanceof HandlerMethod method)
                || method.hasMethodAnnotation(ViewerAllowed.class)) {
            return true;
        }
        String user = request.getHeader("X-User");
        @SuppressWarnings("unchecked")
        Map<String, String> vars = (Map<String, String>) request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        String sheetId = vars == null ? null : vars.getOrDefault("sheetId", vars.get("id"));
        if (user != null && sheetId != null
                && SheetRole.VIEWER.equals(roles.roleOf(sheetId.trim(), user.trim()))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer may change nothing");
        }
        return true;
    }
}

package net.officefloor.hq.app.sheet;


/** Refuses every change asked from a screen showing the sheet as of a date (one sending
 *  {@value #HEADER}) (409), before it writes anything; only the requests marked {@link AsOfAllowed}
 *  go through. */
@Configuration
public class AsOfGuard implements HandlerInterceptor, WebMvcConfigurer {

    /** The header a screen showing the sheet as of a date sends that date (yyyy-mm-dd) in. */
    public static final String HEADER = "X-As-Of";

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this).addPathPatterns("/api/sheets/**");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String asOf = request.getHeader(HEADER);
        if (asOf == null || asOf.isBlank() || HttpMethod.GET.matches(request.getMethod())
                || !(handler instanceof HandlerMethod method) || method.hasMethodAnnotation(AsOfAllowed.class)) {
            return true;
        }
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "The sheet is shown as of a date: it may not be changed from there");
    }
}
package net.officefloor.hq.app.sheet;


/** Refuses every change asked of an archived sheet (409), before it writes anything; only the
 *  requests marked {@link ArchivedAllowed} go through. */
@Configuration
public class ArchivedGuard implements HandlerInterceptor, WebMvcConfigurer {

    private final SheetService sheets;

    public ArchivedGuard(SheetService sheets) {
        this.sheets = sheets;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this).addPathPatterns("/api/sheets/**");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || !(handler instanceof HandlerMethod method)
                || method.hasMethodAnnotation(ArchivedAllowed.class)) {
            return true;
        }
        @SuppressWarnings("unchecked")
        Map<String, String> vars = (Map<String, String>) request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        String sheetId = vars == null ? null : vars.getOrDefault("sheetId", vars.get("id"));
        if (sheetId != null && sheets.archived(sheetId.trim())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived: it may not be changed");
        }
        return true;
    }
}

